  max-width: 1208px;
  margin: 0 auto;
  padding: 80px 24px 60px;
}
.hero-copy {
  min-width: 0;
}
.hero-eyebrow {
  margin: 0 0 24px;
  font-family: var(--vp-font-family-mono);
  font-size: 0.75rem;
  color: var(--vp-c-brand-1);
  line-height: 1.7;
}
.hero-copy h1 {
  font-family: var(--vp-font-family-heading);
  font-size: clamp(3.5rem, 5.6vw, 5rem);
  font-weight: 500;
  letter-spacing: -0.045em;
  line-height: 0.98;
}
.hero-copy h1 em {
  color: var(--vp-c-brand-1);
  font-weight: 400;
}
.hero-lede {
  max-width: 42ch;
  margin: 26px 0 0;
  color: var(--vp-c-text-2);
  font-size: 1.125rem;
  line-height: 1.7;
  text-wrap: pretty;
}
.hero-lede code {
  font-size: 0.9em;
  color: var(--vp-c-text-1);
    margin-inline: 24px;
  }
}
@media (max-width: 960px) {
  .home-hero {
    grid-template-columns: minmax(0, 1fr);
    max-width: 720px;
    gap: 40px;
    padding-top: 48px;
  }
  .hero-copy h1 {
    font-size: clamp(3.5rem, 9vw, 5rem);
  }
  .hero-lede {
    max-width: 48ch;
  }
  .hero-footnote {
    justify-content: center;
    text-align: center;
  }
  .hero-footnote ul {
    justify-content: center;
  }
}
@media (max-width: 640px) {
  .home-hero {
    padding: 40px 24px;
    gap: 32px;
  }
  .hero-eyebrow {
    margin-bottom: 20px;
  }
  .hero-copy h1 {
    font-size: clamp(3rem, 12vw, 4rem);
  }
  .hero-lede {
    font-size: 1rem;
  }
  .hero-break {
    display: none;
  }
  .hero-actions {
    gap: 10px;
  }
  .action-btn {
    padding-inline: 16px;
    gap: 16px;
  }

